        private val SQL_upsertLiveSession: String = """
        INSERT INTO liveSession
            (deviceId, startTs, endTs, chargeAtStart, floorBpm, ceilingBpm,
             inBandSec, belowSec, aboveSec, pushCount, easeCount, hrSource)
        VALUES (:deviceId, :startTs, :endTs, :chargeAtStart, :floorBpm, :ceilingBpm,
                :inBandSec, :belowSec, :aboveSec, :pushCount, :easeCount, :hrSource)
        ON CONFLICT(deviceId, startTs) DO UPDATE SET
            endTs = excluded.endTs,
            chargeAtStart = excluded.chargeAtStart,
            floorBpm = excluded.floorBpm,
            ceilingBpm = excluded.ceilingBpm,
            inBandSec = excluded.inBandSec,
            belowSec = excluded.belowSec,
            aboveSec = excluded.aboveSec,
            pushCount = excluded.pushCount,
            easeCount = excluded.easeCount,
            hrSource = excluded.hrSource
        WHERE excluded.endTs IS NOT NULL OR liveSession.endTs IS NULL
        """
        private val SQL_recentLiveSessions: String = "SELECT * FROM liveSession WHERE deviceId = :deviceId ORDER BY startTs DESC LIMIT :limit"
        private val SQL_prunePpgWaveform: String = "DELETE FROM ppgWaveformSample WHERE deviceId = :deviceId AND ts < " +
            "(SELECT MIN(ts) FROM (SELECT ts FROM ppgWaveformSample WHERE deviceId = :deviceId " +
            "ORDER BY ts DESC LIMIT :keep))"
        private val SQL_pruneEcgWaveform: String = "DELETE FROM ecgWaveformSample WHERE deviceId = :deviceId AND ts < " +
            "(SELECT MIN(ts) FROM (SELECT ts FROM ecgWaveformSample WHERE deviceId = :deviceId " +
            "ORDER BY ts DESC LIMIT :keep))"
        private val SQL_pruneV18Aux: String = "DELETE FROM v18AuxSample WHERE deviceId = :deviceId AND ts < " +
            "(SELECT MIN(ts) FROM (SELECT ts FROM v18AuxSample WHERE deviceId = :deviceId ORDER BY ts DESC LIMIT :keep))"
        private val SQL_sleepSession: String = "SELECT * FROM sleepSession WHERE deviceId = :deviceId AND startTs = :startTs"
        private val SQL_deleteSleepSession: String = "DELETE FROM sleepSession WHERE deviceId = :deviceId AND startTs = :startTs"
        private val SQL_updateSleepStages: String = "UPDATE sleepSession SET stagesJSON = :stagesJSON " +
            "WHERE deviceId = :deviceId AND startTs = :detectedStartTs AND userEdited = 1"
        private val SQL_updateSessionMotion: String = "UPDATE sleepSession SET motionJSON = :json WHERE deviceId = :deviceId AND startTs = :sessionStart"
        private val SQL_sessionMotionJson: String = "SELECT motionJSON FROM sleepSession WHERE deviceId = :deviceId AND startTs = :sessionStart"
        private val SQL_updateSessionSleepState: String = "UPDATE sleepSession SET sleepStateJSON = :json WHERE deviceId = :deviceId AND startTs = :sessionStart"
        private val SQL_sessionSleepStateJson: String = "SELECT sleepStateJSON FROM sleepSession WHERE deviceId = :deviceId AND startTs = :sessionStart"
